head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gProgRsnCd;
scwin.gDelayTm;
scwin.vScrenID = 'ULDSTF10500.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    var strDepCd = js_dep_cd.substring(0, 2);
    //alert("strDepCd-->"+strDepCd); 

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    if (strDepCd == '26' || strDepCd == '34') {
        $c.stf.showObj(panel_2, true);
    } else {
        $c.stf.showObj(panel_2, false);
    }

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //2009.09.01 채권공시 - 채권상장팀인경우..전체를 밴다..		
    //alert("js_bond_yn-->"+js_bond_yn);		
    if (js_bond_yn == "Y") {
        $c.cp.removeRow(dts_dep, 1);
    }

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
    if (scwin.gLdMktTp == '1') {
        $c.stf.setObjectValue(txb_noti_msg, '승인 또는 (익일)승인처리 된 문서 중 승인처리시각 - 접수시각이 20분을 초과한 문서가 리스팅됩니다.');
    } else if (scwin.gLdMktTp == '2') {
        $c.stf.setObjectValue(txb_noti_msg, '승인 또는 (익일)승인처리 된 문서 중 승인처리시각 - 접수시각이 2011.12.12일 부터는 20분, 이전은 30분을 초과한 문서가 리스팅됩니다.');
    } else {
        $c.stf.setObjectValue(txb_noti_msg, '승인 또는 (익일)승인처리 된 문서 중 승인처리시각 - 접수시각이 30분을 초과한 문서가 리스팅됩니다.');
    }
};




// 화면 로딩시 디폴트 검색
scwin.fn_InitSearch = function() {
    //fn_Search();


    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !공시유보현황--;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }

    //

    // 유가 공시팀(26**), 코스닥 공시팀(34**) =>  선택부서로
    //2009.09.01 채권공시 관련 추가  js_bond_yn == "Y"
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34' || js_bond_yn == "Y") {
        scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
        scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    } else {
        scwin.gDepCd = ""; // 부서코드 없음 => 전체	
        scwin.gEmpNo = "";
    }
    fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !공시유보현황--;
클릭-- > function() {
    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
    ******************************************************************/
    if (js_bond_yn == "Y") {
        scwin.gLdMktTp = "4";
    }
    var url = "/DisclosureStatus.do?method=listDisclosureDelay&inputMessageId=DSCLDELAYCOND_IN" + "&outputMessageId=DSCLDELAYLIST_OUT" + "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&TIME_TP=" + $c.stf.getObjectValue(cmb_TimeTp) + "&RSN_1=" + scwin.getChkValue(ckb_rsn_1) + "&RSN_2=" + scwin.getChkValue(ckb_rsn_2) + "&RSN_3=" + scwin.getChkValue(ckb_rsn_3) + "&RSN_4=" + scwin.getChkValue(ckb_rsn_4) + "&RSN_5=" + scwin.getChkValue(ckb_rsn_5) + "&RSN_6=" + scwin.getChkValue(ckb_rsn_6) + "&RSN_7=" + scwin.getChkValue(ckb_rsn_7) + "&RSN_8=" + scwin.getChkValue(ckb_rsn_8) + "&RSN_9=" + scwin.getChkValue(ckb_rsn_9) + "&RSN_10=" + scwin.getChkValue(ckb_rsn_10) + "&LD_MKT_TP=" + scwin.gLdMktTp + "&UP_DEP_CD=" + js_belngdepcd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert('url'+url);

    dts_DelayList.DataID = encodeURI(url);
    dts_DelayList.reset();
    $c.cm.ShowWin(grd_Grid);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DelayList.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DelayList.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_DelayList.getCellData(eval(obj), "FORM_VER");
    gIsurCd = dts_DelayList.getCellData(eval(obj), "ISUR_CD");
    scwin.gProgRsnCd = dts_DelayList.getCellData(eval(obj), "PROG_RSN_CD");
    scwin.gDelayTm = dts_DelayList.getCellData(eval(obj), "DELAY_TM");
    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.dts_DelayList_OnLoadError = function() {
    $c.stf.alert_error(dts_DelayList);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.dts_DelayList_OnLoadCompleted = function(rowcount) {
    if (dts_DelayList.errorMsg) {
        $c.win.alert(dts_DelayList.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R");
    } else if (colid == "DELAY_TM" ||
        colid == "PROG_RSN_NM") {
        // 경과사유 수정
        var url = "/dsclproc/ULDSTF10501.gfm";
        var winTitle = "경과사유 수정";
        await $c.frame.CreateDialogFrame("delay" + scwin.gAcptNo, url, winTitle, 100, 100, 710, 210 + 30, "window");
    } else if (colid == "ACPT_DDTM") {
        $c.stf.fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, "공시유보현황 목록", "", "2");
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_TeamList, js_dep_cd);
};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EmpList, js_emp_no) ;	

};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EmpList, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_com_srch_onclick = function() {
    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 채권종목만...
    ******************************************************************/
    if (js_bond_yn == "Y") {
        $c.cm.IsurcdSearchBond(txb_isur_cd, txb_com_abbrv);
    } else {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    }
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_SetCode();
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_InitSearch();
};
